class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another,
    while also being backed by a real file so it has a valid file
    descriptor. This lets code under test pass these streams to things like
    ``subprocess.run(..., stdout=sys.stdout)``, which requires ``fileno()``
    to work.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._file = tempfile.TemporaryFile()

    def flush(self) -> None:
        super().flush()
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        self._file.write(b)
        return super().write(b)

    def fileno(self) -> int:
        return self._file.fileno()

